# ── GAT ASSURANCES — 14-15 branches + Montant (« Total »), valeurs SIGNÉES,
# modèle additif comme COMAR (Solde de souscription = Primes acquises +
# Charges de prestations, etc.). Pages Annexe 13 en couche texte native, très
# fragmentée : reconstruction géométrique (bord droit des colonnes déduit de
# la ligne « Résultat technique » pleine, sinon clustering des x des nombres
# de toutes les lignes), gestion des négatifs entre parenthèses (millésimes
# en dinars entiers) OU préfixe -/‐ (millésimes en millimes), et re-découpe
# des nombres fusionnés sans espace entre 2 colonnes. Toutes les identités
# vérifiées, écart nul — SAUF l'anomalie DANS LE PDF sur 2017 et 2023 : une
# valeur (22 643,34 en 2017 sur Acceptation ; 244 294 en 2023 sur Montant)
# est déplacée entre « Charges d'acquisition et de gestion nettes » et
# « Solde financier » (les 2 écarts s'annulent exactement) — valeurs laissées
# telles qu'imprimées.
