# ── ASTREE — gabarit le plus fragmenté (en-têtes lettre-à-lettre, 3 colonnes
# « Total non vie » / Acceptations / « Total » quasi adjacentes, signes
# mélangés <...> / (...) / -). Reconstruction géométrique dédiée : bords de
# colonnes = x1 des nombres de la ligne « Résultat technique (AAAA) »,
# signe « moins » détaché géré, nombres collés sans espace re-découpés.
# Modèle additif : SS = Primes(acquises) + Variation + Prestations payées +
# Charges provisions ; CAG = FA + Autres ch. gestion ; SF = Produits
# placements + Participation ; SR = Σ parts réassureurs ; RT = SS+CAG+SF+SR.
# 6 millésimes propres (identités écart nul) ; 2015 (2 résidus d'arrondi
# source, table en milliers), 2017 (« ##### » dans le PDF sur la ligne Solde
# de souscription), 2018 restent à reprendre ; 2022/2023 = Annexe 13 scannée.
_R_AST = [
    'Primes acquises',
    'Variation des primes non acquises',
    'Prestations et frais payés',
    'Charges des provisions pour prestations diverses',
    'Solde de souscription',
    "Frais d'acquisition",
    'Autres charges de gestion nettes',
    "Charges d'acquisition et de gestion nettes",
    'Produits nets de placements',
    'Participation aux résultats',
    'Solde financier',
    'Part des réassureurs dans les primes acquises',
    'Part des réassureurs dans la variation des primes non acquises',
    'Part des réassureurs dans les prestations payées',
    'Part des réassureurs dans les charges de provisions pour prestations',
    'Commissions reçues des réassureurs / rétrocessionnaires',
    'Solde de réassurance / rétrocession',
    'Résultat technique',
]
_AST_COLS_17 = ["Automobile", "Transport", "Aviation", "Incendie", "Responsabilité décennale",
                "Responsabilité civile", "Risques agricoles", "Autres dommages aux biens",
                "Assistance", "Crédit-Caution", "Maladie", "Invalidité", "Individuelle accident",
                "Loi", "Total non vie", "Acceptation", "Total"]
