# permutees, valeurs de cellule enroulees sur 2-3 lignes. La C7, elle, est
# propre. On fige donc ces 4 millesimes sur la C7 (2019 & 2021 gardent leur
# C4 7 colonnes, ci-dessus). Identites C7 verifiees :
