#   -122 997 deja agregees) ; SF = Produits nets placements + Participation ;
#   SR = Primes cedees + RA(primes) + RA(prest.) + RA(ch. prov.) + Commissions ;
#   RT = SS + CAG + SF + SR (+ Autres charges tech. quand hors CAG).
