# ── CARTE — Annexe 13 « Résultat technique par catégorie d'assurance non
# vie ». Calque texte propre mais en-têtes de colonnes inexploitables
# (numérotées « 1-AUTO », tronquées, caractères entrelacés en 2025) ->
# reconstruction géométrique (scratchpad/carte.py) : bords de colonnes =
# centres des nombres d'une ligne pleine ; noms de colonnes = liste fixe
# par époque. Valeurs en millimes arrondies au dinar. Modèle additif
# entièrement signé (SS = PE + Var.PNA + Prest. + Ch. prov. ;
# CAG = Frais d'acq. + Autres charges de gestion nettes ;
# SF = Produits nets placements + Participation ;
# SR = Σ Part réassureurs (primes/prest./ch.prov.) + Commissions ;
# RT = SS + CAG + SF + SR) + contrôle horizontal Σ branches = Total.
# Toutes années : écart nul. 2020 : pas d'Annexe 13 par catégorie dans le
# dépôt. 2023 : page scannée.
