# ── TUNIS RE — Annexe 13 « RESULTAT TECHNIQUE PAR CATEGORIE » (principale).
# 10 colonnes : Incendie / ARD / Risques techniques / Total non marines /
# Transport / Aviation / Total marines / Total non vie / Vie / Total.
# Calque texte à ESPACES PARASITES dans les grands nombres (« 6 4 744 348 »
# = 64 744 348) : chaque fragment de chiffres est assigné à sa colonne
# puis RE-CONCATÉNÉ dans l'ordre des x ; « - » isolé (signe) rattaché à la
# colonne du fragment SUIVANT ; « libellé- » collé = signe négatif de la
# 1re colonne ; colonnes agrégées recalculées depuis les atomiques ;
# libellés éclatés sur 2-3 lignes recollés ; 2018 : dé-fusion de la ligne
# « Autres charges de gestion nettes » + libellé CAG collés par pdfplumber ;
# 2020 : bords de colonnes re-dérivés d'une ligne pleine de référence quand
# le clustering global donne des colonnes fusionnées (scratchpad/tunisre.py).
# Charges en MAGNITUDE positive -> faux positifs validate_table documentés.
# Modèle : SS = PA − CP ; CAG = FA + Autres charges de gestion nettes ;
# Solde financier = Produits nets de placements + (SS − CAG) ;
# SR = Part rétro.(primes) − Part rétro.(prest) − Part rétro.(ch.prov) −
# Part rétro.(participation) − Commissions − Wakala (ligne « Wakala » =
# frais rétakaful, présente dès 2019) ; RT = Solde financier − SR.
# Contrôles horizontaux : Total non marines = Incendie+ARD+Risques tech ;
# Total marines = Transport+Aviation ; Total non vie = TnM+TM ;
# Total = Total non vie + Vie.
# 2015-2016, 2018-2025 : toutes identités écart nul. 2017 : le PDF SOURCE
# est lui-même incohérent sur RT « Transport »/« Total marines »/« Total
# non vie »/« Total » (RT imprimé 1 953 727 alors que SF − SR = 594 788)
# -> 4 écarts validate_table = erreur de la source, valeurs conservées
# telles qu'imprimées (cf. BH 2023).
